const input = $input.first().json;
const workflows = input.data ?? [];

if (!Array.isArray(workflows) || workflows.length === 0) {
  throw new Error('No workflows received from n8n API');
}

function sanitize(value, key = '') {
  const sensitiveKey =
    /password|passwd|secret|token|api[_-]?key|authorization|private[_-]?key|access[_-]?key/i;

  if (sensitiveKey.test(key)) {
    return '[REDACTED - CONFIGURE MANUALLY]';
  }

  if (Array.isArray(value)) {
    return value.map(item => sanitize(item));
  }

  if (value && typeof value === 'object') {
    const result = {};
    for (const [k, v] of Object.entries(value)) {
      result[k] = sanitize(v, k);
    }
    return result;
  }

  if (typeof value === 'string') {
    return value
      .replace(/\b(Bearer\s+)[A-Za-z0-9._~+/=-]+/gi, '$1[REDACTED]')
      .replace(/\bgh[pousr]_[A-Za-z0-9]{20,}\b/g, '[REDACTED_GITHUB_TOKEN]')
      .replace(/\bsk-[A-Za-z0-9_-]{20,}\b/g, '[REDACTED_API_KEY]');
  }

  return value;
}

function slugify(name) {
  const slug = String(name ?? 'workflow')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 70);

  return slug || 'workflow';
}

return workflows.map(workflow => {
  if (!workflow.id || !workflow.name) {
    throw new Error('Workflow is missing its ID or name');
  }

  const nodes = (workflow.nodes ?? []).map(node => {
    const { credentials, ...nodeWithoutCredentials } = node;
    return sanitize(nodeWithoutCredentials);
  });

  const backup = sanitize({
    name: workflow.name,
    nodes,
    connections: workflow.connections ?? {},
    settings: workflow.settings ?? {},
    tags: workflow.tags ?? []
  });

  const filename = `${slugify(workflow.name)}-${workflow.id}.json`;
  const content = JSON.stringify(backup, null, 2);

  return {
    json: {
      workflowId: workflow.id,
      workflowName: workflow.name,
      path: `workflows/${filename}`,
      content,
      contentBase64: Buffer.from(content, 'utf8').toString('base64').trim()
    }
  };
});
